const priorShow=showSkillDemo;showSkillDemo=function(i){priorShow(i);document.querySelector('#demo-detail .demo-output').innerHTML='<figcaption>效果预览 · 示意</figcaption><div class="visual-preview">'+previews[i]+'</div>';document.querySelector('#demo-image').remove()};showSkillDemo(0);
