const originalSkillsRender=renderSkills;
renderSkills=function(){originalSkillsRender();document.querySelectorAll('#skill-grid .skill-card').forEach(card=>{const name=card.querySelector('h3')?.textContent;const index=skillDemos.findIndex(d=>d[0]===name);if(index<0)return;const panel=document.createElement('div');panel.className='card-demo';panel.innerHTML='<div class="card-demo-label">效果预览 <span>示意</span></div><div class="card-demo-canvas">'+previews[index]+'</div>';card.querySelector('.skill-source').before(panel)})};
document.querySelector('.skill-showcase').remove();renderSkills();
